from pathlib import Path
p=Path('src/features/auth/SignIn.tsx');s=p.read_text()
s=s.replace('import "./SignIn.css";', 'import "./SignIn.css";\nimport {useDialogFocus} from "../../components/useDialogFocus";')
s=s.replace(' const [recoveryHelp,setRecoveryHelp]=useState(false);',''' const [recoveryHelp,setRecoveryHelp]=useState(false),[recoveryUsername,setRecoveryUsername]=useState(''),[recoveryEmail,setRecoveryEmail]=useState(''),[recoveryBusy,setRecoveryBusy]=useState(false),[recoveryError,setRecoveryError]=useState(''),[recoverySuccess,setRecoverySuccess]=useState('');
 const recoveryDialog=useDialogFocus<HTMLElement>(recoveryHelp,()=>setRecoveryHelp(false),recoveryBusy);
 const recover=async(event:FormEvent)=>{event.preventDefault();if(recoveryBusy)return;setRecoveryBusy(true);setRecoveryError('');try{const result=await enforcementApi.forgotPassword(recoveryUsername,recoveryEmail);setRecoverySuccess(result.message);}catch(error){setRecoveryError((error as Error).message);}finally{setRecoveryBusy(false);}};''')
s=s.replace('onClick={()=>setRecoveryHelp(v=>!v)}', "onClick={()=>{setRecoveryUsername(username);setRecoveryEmail('');setRecoveryError('');setRecoverySuccess('');setRecoveryHelp(true);}}")
s=s.replace('       {recoveryHelp&&<p id="ef-recovery" className="ef-auth-help" role="status">Contact your Master Administrator to request a temporary password. Automated password recovery is not available.</p>}\n','')
s=s.replace('   <footer className="ef-auth-footer">','''   {recoveryHelp&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget&&!recoveryBusy)setRecoveryHelp(false);}}><section id="ef-recovery" ref={recoveryDialog} className="keyboard-dialog recovery-dialog" role="dialog" aria-modal="true" aria-labelledby="recovery-title"><header><h2 id="recovery-title">Request a password reset</h2><button type="button" className="action-secondary" disabled={recoveryBusy} onClick={()=>setRecoveryHelp(false)}>Close</button></header><p>Enter both details exactly as saved by your administrator. A matching account sends a request to the Master Administrator.</p>{recoverySuccess?<><p className="portal-message" role="status">{recoverySuccess}</p><button className="action-primary" onClick={()=>setRecoveryHelp(false)}>Back to sign in</button></>:<form onSubmit={recover}><label className="portal-field">Official username<input autoFocus required maxLength={80} autoComplete="username" autoCapitalize="none" disabled={recoveryBusy} value={recoveryUsername} onChange={e=>setRecoveryUsername(e.target.value)}/></label><label className="portal-field">Registered email address<input required type="email" maxLength={254} autoComplete="email" disabled={recoveryBusy} value={recoveryEmail} onChange={e=>setRecoveryEmail(e.target.value)}/></label>{recoveryError&&<p className="ef-auth-error" role="alert">{recoveryError}</p>}<button className="action-primary" disabled={recoveryBusy}>{recoveryBusy?'Checking account…':'Send recovery request'}</button></form>}</section></div>}
   <footer className="ef-auth-footer">''')
p.write_text(s)
p=Path('src/features/workspaces/WorkspaceEditButton.tsx');s=p.read_text()
s=s.replace('name:string;role:string;active?', 'name:string;email?:string|null;role:string;active?')
s=s.replace('name:user.name,role:user.role', "name:user.name,email:user.email??'',role:user.role")
s=s.replace('<label className="portal-field">Access role', '<label className="portal-field">Official email address<input type="email" required maxLength={254} value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label className="portal-field">Access role')
p.write_text(s)
